func:
flow.set("last_request", msg.payload);
// Also keyed by contract: "was the PDP consulted for THIS interaction" cannot
// be answered from the global last request — any earlier consult, from any
// other scenario, already satisfies that. The per-contract entry is what a
// caller asserts against (GET /trust-pdp/last?contractDID=...).
const contractDID = (msg.payload && msg.payload.contractDID) || "";
if (contractDID) {
  const byContract = flow.get("requests_by_contract") || {};
  byContract[contractDID] = msg.payload;
  flow.set("requests_by_contract", byContract);
}
const mode = flow.get("mode") || "allow";
if (mode === "silent") {
  // Simulates an unreachable policy endpoint: no output at all, so the
  // downstream http response node never fires and the caller's HTTP
  // request hangs until its own client-side timeout (ADR-19 fail-closed:
  // an unreachable endpoint must deny exactly like an explicit deny).
  return null;
}
msg.headers = { "Content-Type": "application/json" };
if (mode === "deny") {
  msg.statusCode = 403;
  msg.payload = { decision: "deny" };
} else {
  msg.statusCode = 200;
  msg.payload = { decision: "allow" };
}
return msg;

const requested = (msg.payload && msg.payload.mode) || "";
const allowed = ["allow", "deny", "silent"];
if (!allowed.includes(requested)) {
  msg.statusCode = 400;
  msg.headers = { "Content-Type": "application/json" };
  msg.payload = { error: `mode must be one of ${allowed.join(", ")}`, got: requested };
  return msg;
}
flow.set("mode", requested);
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = { mode: requested };
return msg;

// Without ?contractDID= this reports the most recent request of any
// interaction; with it, the most recent request that named that contract —
// the only form that proves a consult happened for one specific interaction
// rather than at some earlier point in the run.
const contractDID = (msg.req && msg.req.query && msg.req.query.contractDID) || "";
const last = contractDID
  ? (flow.get("requests_by_contract") || {})[contractDID]
  : flow.get("last_request");
msg.headers = { "Content-Type": "application/json" };
if (last === undefined) {
  msg.statusCode = 404;
  msg.payload = contractDID
    ? { error: "no request captured for this contract yet", contractDID: contractDID }
    : { error: "no request captured yet" };
} else {
  msg.statusCode = 200;
  msg.payload = last;
}
return msg;
